// Validation — leased bicycle deposit check
// ============================================================================

/**
 * Check if any bicycle line items in the order reference a leased bicycle.
 * Throws LeasedBicycleDepositError if a lease is found and deposit > 0.
 */
async function validateNoLeasedBicyclesWithDeposit(
  lineItems: CreateCustomerOrderInput['lineItems'],
  depositAmount: number
): Promise<void> {
  if (depositAmount <= 0) return

  // Find all bicycle IDs from bicycle-type line items
  const bicycleIds = lineItems
    .filter(item => item.lineType === 'bicycle' && item.bicycleId)
    .map(item => item.bicycleId!)

  if (bicycleIds.length === 0) return

  // Check if any of these bicycles are leased
  const leasedBikes = await db
    .select({ id: bicycles.id, isLease: bicycles.isLease })
    .from(bicycles)
    .where(sql`${bicycles.id} IN (${sql.join(bicycleIds)}) AND ${bicycles.isLease} = 1`)

  if (leasedBikes.length > 0) {
    throw new LeasedBicycleDepositError()
  }
}

