    await db.delete(customerOrders)
    await db.delete(vatRates)
    try { await db.delete(bicycles) } catch {}
    try { await db.delete(sequences).where(eq(sequences.name, 'customer_order')) } catch {}
    try { await db.delete(sequences).where(eq(sequences.name, 'sale')) } catch {}
  }

  beforeEach(async () => {
    await resetTables()
    // Seed VAT rate used by all tests
    await db.insert(vatRates).values({ id: 'vat-standard', rate: 2100, description: 'Standard 21%' })
  })

  // Helper: create an order via the service (reuse existing createCustomerOrder)
  async function createTestOrder(depositAmount = 0) {
    const { createCustomerOrder } = await import('../customer-order.service.js')
    return createCustomerOrder({
      customerId: 'cust-abc',
      lineItems: [
        { lineType: 'part' as const, partId: 'p1', description: 'Part A', quantity: 2, unitPriceNet: 1000, vatRateId: 'vat-standard' },
      ],
      ...(depositAmount > 0 ? { depositAmount, paymentMethod: 'cash' as const } : {}),
    })
  }

  // ============================================================================
  // transitionCustomerOrder — Status transitions with validation + history
  // ============================================================================

  describe('transitionCustomerOrder', () => {
    it('(tracer) should transition pending → ordered and record history', async () => {
      const { transitionCustomerOrder } = await import('../customer-order.service.js')
      const order = await createTestOrder()

      const result = await transitionCustomerOrder(order.order.id, 'ordered')

      expect(result.status).toBe('ordered')
      // History entry created
      const history = await db.select().from(customerOrderStatusHistory).where(eq(customerOrderStatusHistory.orderId, order.order.id))
      expect(history).toHaveLength(1)
      expect(history[0].status).toBe('ordered')
    })

    it('should transition ordered → ready', async () => {
      const { transitionCustomerOrder } = await import('../customer-order.service.js')
      const order = await createTestOrder()
      await transitionCustomerOrder(order.order.id, 'ordered')

      const result = await transitionCustomerOrder(order.order.id, 'ready')
      expect(result.status).toBe('ready')
    })

    it('should transition ready → fulfilled', async () => {
      const { transitionCustomerOrder } = await import('../customer-order.service.js')
      const order = await createTestOrder()
      await transitionCustomerOrder(order.order.id, 'ordered')
      await transitionCustomerOrder(order.order.id, 'ready')

      const result = await transitionCustomerOrder(order.order.id, 'fulfilled')
      expect(result.status).toBe('fulfilled')
    })

    it('should allow cancel from any non-terminal status', async () => {
      const { transitionCustomerOrder } = await import('../customer-order.service.js')
      const order = await createTestOrder()

      // Cancel from pending
      let result = await transitionCustomerOrder(order.order.id, 'cancelled')
      expect(result.status).toBe('cancelled')
    })

    it('should reject invalid transitions', async () => {
      const { transitionCustomerOrder, InvalidTransitionError } = await import('../customer-order.service.js')
      const order = await createTestOrder()

      // pending → fulfilled (skips ordered + ready) should fail
      await expect(transitionCustomerOrder(order.order.id, 'fulfilled')).rejects.toThrow(InvalidTransitionError)
    })

    it('should reject transition from terminal state', async () => {
      const { transitionCustomerOrder, InvalidTransitionError } = await import('../customer-order.service.js')
      const order = await createTestOrder()
      await transitionCustomerOrder(order.order.id, 'ordered')
      await transitionCustomerOrder(order.order.id, 'ready')
      await transitionCustomerOrder(order.order.id, 'fulfilled')

      // fulfilled → anything should fail
      await expect(transitionCustomerOrder(order.order.id, 'ordered')).rejects.toThrow(InvalidTransitionError)
    })

    it('should reject duplicate status transition', async () => {
      const { transitionCustomerOrder, InvalidTransitionError } = await import('../customer-order.service.js')
      const order = await createTestOrder()

      // pending → pending (no change) should fail
      await expect(transitionCustomerOrder(order.order.id, 'pending')).rejects.toThrow(InvalidTransitionError)
    })

    it('should set expectedDeliveryDate when provided during transition', async () => {
      const { transitionCustomerOrder } = await import('../customer-order.service.js')
      const order = await createTestOrder()
      const deliveryDate = new Date('2026-07-15').toISOString()

      const result = await transitionCustomerOrder(order.order.id, 'ordered', { expectedDeliveryDate: deliveryDate })
      expect(result.expectedDeliveryDate).toBeInstanceOf(Date)
    })

    it('should set internalNotes when provided during transition', async () => {
      const { transitionCustomerOrder } = await import('../customer-order.service.js')
      const order = await createTestOrder()

      const result = await transitionCustomerOrder(order.order.id, 'ordered', { internalNotes: 'Rush order' })
      expect(result.internalNotes).toBe('Rush order')
    })

    it('should throw for non-existent order', async () => {
      const { transitionCustomerOrder } = await import('../customer-order.service.js')
      await expect(transitionCustomerOrder('nonexistent-id', 'ordered')).rejects.toThrow(/not found/i)
    })

    it('should create notification when transitioning to ready', async () => {
      const { transitionCustomerOrder } = await import('../customer-order.service.js')
      // Insert a customer with SMS preference
      await db.insert(customerOrders).values({
        id: 'order-with-customer',
        orderNumber: 'CO-TEST1',
        customerId: 'cust-sms',
        status: 'ordered',
        totalPriceNet: 2000,
        createdAt: new Date(),
      })

      await transitionCustomerOrder('order-with-customer', 'ready')

      const notificationRows = await db.select().from(notifications)
      expect(notificationRows.length).toBeGreaterThan(0)
    })
  })

  // ============================================================================
  // updateCustomerOrderFields — Editable fields with guards
  // ============================================================================

  describe('updateCustomerOrderFields', () => {
    it('(tracer) should update internalNotes on pending order', async () => {
      const { updateCustomerOrderFields } = await import('../customer-order.service.js')
      const order = await createTestOrder()

      const result = await updateCustomerOrderFields(order.order.id, { internalNotes: 'Updated notes' })
      expect(result.internalNotes).toBe('Updated notes')
    })

    it('should update expectedDeliveryDate on ordered order', async () => {
      const { transitionCustomerOrder, updateCustomerOrderFields } = await import('../customer-order.service.js')
      const order = await createTestOrder()
      await transitionCustomerOrder(order.order.id, 'ordered')

      const deliveryDate = new Date('2026-08-01').toISOString()
      const result = await updateCustomerOrderFields(order.order.id, { expectedDeliveryDate: deliveryDate })
      expect(result.expectedDeliveryDate).toBeInstanceOf(Date)
    })

    it('should allow updates through ready status', async () => {
      const { transitionCustomerOrder, updateCustomerOrderFields } = await import('../customer-order.service.js')
      const order = await createTestOrder()
      await transitionCustomerOrder(order.order.id, 'ordered')
      await transitionCustomerOrder(order.order.id, 'ready')

      // Should still be editable at ready status
      const result = await updateCustomerOrderFields(order.order.id, { internalNotes: 'Final notes' })
      expect(result.internalNotes).toBe('Final notes')
    })

    it('should reject updates on fulfilled order (403)', async () => {
      const { transitionCustomerOrder, updateCustomerOrderFields, EditabilityError } = await import('../customer-order.service.js')
      const order = await createTestOrder()
      await transitionCustomerOrder(order.order.id, 'ordered')
      await transitionCustomerOrder(order.order.id, 'ready')

      // Complete the order (fulfilled) — use direct DB update for this test since completeOrder is tested separately
      await db.update(customerOrders).set({ status: 'fulfilled' }).where(eq(customerOrders.id, order.order.id))

      await expect(updateCustomerOrderFields(order.order.id, { internalNotes: 'Should fail' })).rejects.toThrow(EditabilityError)
    })

    it('should reject updates on cancelled order (403)', async () => {
      const { transitionCustomerOrder, updateCustomerOrderFields, EditabilityError } = await import('../customer-order.service.js')
      const order = await createTestOrder()
      await transitionCustomerOrder(order.order.id, 'cancelled')

      await expect(updateCustomerOrderFields(order.order.id, { internalNotes: 'Should fail' })).rejects.toThrow(EditabilityError)
    })

    it('should throw for non-existent order', async () => {
      const { updateCustomerOrderFields } = await import('../customer-order.service.js')
      await expect(updateCustomerOrderFields('nonexistent-id', { internalNotes: 'test' })).rejects.toThrow(/not found/i)
    })

    it('should reject empty update payload', async () => {
      const { updateCustomerOrderFields } = await import('../customer-order.service.js')
      const order = await createTestOrder()

      // Passing empty object — TypeScript allows this but runtime should reject
      await expect(updateCustomerOrderFields(order.order.id, {} as any)).rejects.toThrow(/nothing to update/i)
    })
  })

  // ============================================================================
  // completeCustomerOrder — Balance collection → sale record → fulfilled
  // ============================================================================

  describe('completeCustomerOrder', () => {
    it('(tracer) should collect balance and create sale for order with deposit', async () => {
      const { completeCustomerOrder } = await import('../customer-order.service.js')
      const order = await createTestOrder(500) // 2000 total, 500 deposit → 1500 balance

      const result = await completeCustomerOrder(order.order.id, [
        { method: 'cash', amount: 1500 },
      ])

      // Order is fulfilled
      expect(result.order.status).toBe('fulfilled')

      // Sale created with correct sourceType
      expect(result.sale.sourceType).toBe('customer_order')
      expect(result.sale.sourceId).toBe(order.order.id)

      // Payment record created for balance
      expect(result.payments[0].amount).toBe(1500)
    })

    it('should collect balance with multiple payment methods', async () => {
      const { completeCustomerOrder } = await import('../customer-order.service.js')
      const order = await createTestOrder(500) // 2000 total, 500 deposit → 1500 balance

      const result = await completeCustomerOrder(order.order.id, [
        { method: 'cash', amount: 800 },
        { method: 'card', amount: 700 },
      ])

      expect(result.order.status).toBe('fulfilled')
      // Two payments created
      expect(result.payments).toHaveLength(2)
    })

    it('should create sale with line items copied from order', async () => {
      const { completeCustomerOrder } = await import('../customer-order.service.js')
      const order = await createTestOrder(500)

      const result = await completeCustomerOrder(order.order.id, [
        { method: 'cash', amount: 1500 },
      ])

      expect(result.saleLineItems).toHaveLength(1)
      expect(result.saleLineItems[0].description).toBe('Part A')
    })

    it('should reject when payment lines do not cover balance due', async () => {
      const { completeCustomerOrder, InsufficientPaymentError } = await import('../customer-order.service.js')
      const order = await createTestOrder(500) // 2000 total, 500 deposit → 1500 balance

      await expect(completeCustomerOrder(order.order.id, [
        { method: 'cash', amount: 1000 }, // only 1000 of 1500 needed
      ])).rejects.toThrow(InsufficientPaymentError)
    })

    it('should reject when payment lines exceed balance due', async () => {
      const { completeCustomerOrder, InsufficientPaymentError } = await import('../customer-order.service.js')
      const order = await createTestOrder(500) // 2000 total, 500 deposit → 1500 balance

      await expect(completeCustomerOrder(order.order.id, [
        { method: 'cash', amount: 2000 }, // exceeds 1500 needed
      ])).rejects.toThrow(InsufficientPaymentError)
    })

    it('should complete order with no deposit (full balance = totalPriceNet)', async () => {
      const { completeCustomerOrder } = await import('../customer-order.service.js')
      const order = await createTestOrder() // 2000 total, 0 deposit → 2000 balance

      const result = await completeCustomerOrder(order.order.id, [
        { method: 'card', amount: 2000 },
      ])

      expect(result.order.status).toBe('fulfilled')
      expect(result.payments[0].amount).toBe(2000)
    })

    it('should reject completing already fulfilled order', async () => {
      const { completeCustomerOrder } = await import('../customer-order.service.js')
      const order = await createTestOrder()
      await completeCustomerOrder(order.order.id, [{ method: 'cash', amount: 2000 }])

      // Try to complete again
      await expect(completeCustomerOrder(order.order.id, [{ method: 'cash', amount: 2000 }])).rejects.toThrow(/already fulfilled/i)
    })

    it('should reject completing cancelled order', async () => {
      const { transitionCustomerOrder, completeCustomerOrder } = await import('../customer-order.service.js')
      const order = await createTestOrder()
      await transitionCustomerOrder(order.order.id, 'cancelled')

      await expect(completeCustomerOrder(order.order.id, [{ method: 'cash', amount: 2000 }])).rejects.toThrow(/Cannot complete a cancelled order/)
    })

    it('should throw for non-existent order', async () => {
      const { completeCustomerOrder } = await import('../customer-order.service.js')
      await expect(completeCustomerOrder('nonexistent-id', [{ method: 'cash', amount: 1000 }])).rejects.toThrow(/not found/i)
    })
  })

  // ============================================================================
  // cancelCustomerOrder — Cancel with refund rules
  // ============================================================================

  describe('cancelCustomerOrder', () => {
    it('(tracer) should cancel pending order and reverse deposit allocation', async () => {
      const { cancelCustomerOrder } = await import('../customer-order.service.js')
      const order = await createTestOrder(500) // with deposit

      const result = await cancelCustomerOrder(order.order.id)

      expect(result.status).toBe('cancelled')
      // Refund payment created
      expect(result.refundPayment).toBeDefined()
      expect(result.refundPayment!.amount).toBe(500)
    })

    it('should not create refund when cancelling pending order with no deposit', async () => {
      const { cancelCustomerOrder } = await import('../customer-order.service.js')
      const order = await createTestOrder() // no deposit

      const result = await cancelCustomerOrder(order.order.id)

      expect(result.status).toBe('cancelled')
      expect(result.refundPayment).toBeUndefined()
    })

    it('should NOT refund deposit when cancelling at ordered status', async () => {
      const { transitionCustomerOrder, cancelCustomerOrder } = await import('../customer-order.service.js')
      const order = await createTestOrder(500) // with deposit
      await transitionCustomerOrder(order.order.id, 'ordered')

      const result = await cancelCustomerOrder(order.order.id)

      expect(result.status).toBe('cancelled')
      // No refund at ordered status — deposit is non-refundable
      expect(result.refundPayment).toBeUndefined()
    })

    it('should NOT refund deposit when cancelling at ready status', async () => {
      const { transitionCustomerOrder, cancelCustomerOrder } = await import('../customer-order.service.js')
      const order = await createTestOrder(500) // with deposit
      await transitionCustomerOrder(order.order.id, 'ordered')
      await transitionCustomerOrder(order.order.id, 'ready')

      const result = await cancelCustomerOrder(order.order.id)

      expect(result.status).toBe('cancelled')
      expect(result.refundPayment).toBeUndefined()
    })

    it('should reject cancelling already fulfilled order', async () => {
      const { transitionCustomerOrder, cancelCustomerOrder } = await import('../customer-order.service.js')
      const order = await createTestOrder()
      await transitionCustomerOrder(order.order.id, 'ordered')
      await transitionCustomerOrder(order.order.id, 'ready')

      // Manually set to fulfilled for this test (completeOrder tested separately)
      await db.update(customerOrders).set({ status: 'fulfilled' }).where(eq(customerOrders.id, order.order.id))

      await expect(cancelCustomerOrder(order.order.id)).rejects.toThrow(/Cannot cancel a fulfilled order/)
    })

    it('should reject cancelling already cancelled order', async () => {
      const { transitionCustomerOrder, cancelCustomerOrder } = await import('../customer-order.service.js')
      const order = await createTestOrder()
      await transitionCustomerOrder(order.order.id, 'cancelled')

      await expect(cancelCustomerOrder(order.order.id)).rejects.toThrow(/already cancelled/i)
    })

    it('should throw for non-existent order', async () => {
      const { cancelCustomerOrder } = await import('../customer-order.service.js')
      await expect(cancelCustomerOrder('nonexistent-id')).rejects.toThrow(/not found/i)
    })
  })

  // ============================================================================
  // getCustomerOrderHistory — Status transition history
  // ============================================================================

  describe('getCustomerOrderHistory', () => {
    it('(tracer) should return empty array for order with no transitions', async () => {
      const { getCustomerOrderHistory } = await import('../customer-order.service.js')
      const order = await createTestOrder()

      const history = await getCustomerOrderHistory(order.order.id)
      expect(history).toEqual([])
    })

    it('should return transitions in chronological order (oldest first)', async () => {
      const { transitionCustomerOrder, getCustomerOrderHistory } = await import('../customer-order.service.js')
      const order = await createTestOrder()

      await transitionCustomerOrder(order.order.id, 'ordered')
      // Small delay to ensure different timestamps
      await new Promise(r => setTimeout(r, 10))
      await transitionCustomerOrder(order.order.id, 'ready')

      const history = await getCustomerOrderHistory(order.order.id)

      expect(history).toHaveLength(2)
      expect(history[0].status).toBe('ordered')
      expect(history[1].status).toBe('ready')
    })

    it('should throw for non-existent order', async () => {
      const { getCustomerOrderHistory } = await import('../customer-order.service.js')
      await expect(getCustomerOrderHistory('nonexistent-id')).rejects.toThrow(/not found/i)
    })
  })
})

/**
 * Order Detail Panel — Shows order header, line items table, deposit info, status transitions,
 * balance collection dialog, cancel confirmation with refund info, and status history timeline.
 */

import { useState, useEffect, useCallback } from 'react'
import { useNavigate } from 'react-router-dom'
import toast from 'react-hot-toast'
import { ArrowLeft, Package, Wrench, Bike, Clock, CheckCircle2, XCircle, AlertTriangle, CalendarDays, History } from 'lucide-react'
import type { CustomerOrderStatus } from '../types.js'
import { ORDER_STATUS_LABELS, ORDER_STATUS_COLORS, LINE_TYPE_LABELS } from '../types.js'
import {
  getOrder,
  transitionOrder,
  completeOrder,
  cancelOrder,
  getOrderHistory,
  type OrderDetailApiResponse,
} from '../api.js'
import { formatCentsToEuro } from '@/shared/lib/utils'
import { CardContent, CardHeader, CardTitle } from '@/components/ui/card'
import { Button } from '@/components/ui/button'
import { Dialog, DialogContent, DialogHeader, DialogFooter, DialogTitle, DialogDescription } from '@/components/ui/dialog'

// ---------------------------------------------------------------------------
// Types
// ---------------------------------------------------------------------------

interface OrderDetailPanelProps {
  orderId: string
}

/** Status transitions allowed from each state */
const STATUS_TRANSITIONS: Record<CustomerOrderStatus, Array<{ to: CustomerOrderStatus; label: string; action?: 'transition' | 'complete' | 'cancel' }>> = {
  pending: [
    { to: 'ordered', label: 'Mark Ordered', action: 'transition' },
    { to: 'cancelled', label: 'Cancel Order', action: 'cancel' },
  ],
  ordered: [
    { to: 'ready', label: 'Mark Ready for Pickup', action: 'transition' },
    { to: 'cancelled', label: 'Cancel Order', action: 'cancel' },
  ],
  ready: [
    { to: 'fulfilled', label: 'Complete & Collect Balance', action: 'complete' },
    { to: 'cancelled', label: 'Cancel Order', action: 'cancel' },
  ],
  fulfilled: [], // terminal state
  cancelled: [], // terminal state
}

// ---------------------------------------------------------------------------
// Component — Status Badge
// ---------------------------------------------------------------------------

function StatusBadge({ status }: { status: CustomerOrderStatus }) {
  return (
    <span className={`inline-flex items-center rounded-full px-2.5 py-0.5 text-xs font-medium ${ORDER_STATUS_COLORS[status]}`}>
      {ORDER_STATUS_LABELS[status]}
    </span>
  )
}

// ---------------------------------------------------------------------------
// Component — Line Type Icon
// ---------------------------------------------------------------------------

function LineTypeIcon({ lineType }: { lineType: string }) {
  switch (lineType) {
    case 'part': return <Package className="h-4 w-4 text-muted-foreground" />
    case 'labor': return <Wrench className="h-4 w-4 text-muted-foreground" />
    case 'bicycle': return <Bike className="h-4 w-4 text-muted-foreground" />
    default: return null
  }
}

// ---------------------------------------------------------------------------
// Component — Date Formatter
// ---------------------------------------------------------------------------

function formatDate(epochMs: number | null): string {
  if (!epochMs) return '—'
  return new Date(epochMs).toLocaleDateString('en-IE', {
    year: 'numeric',
    month: 'short',
    day: '2-digit',
  })
}

// ---------------------------------------------------------------------------
// Component — Status History Timeline
// ---------------------------------------------------------------------------

interface HistoryEntry {
  id: string
  orderId: string
  status: string
  transitionedAt: number
}

function StatusHistoryTimeline({ history }: { history: HistoryEntry[] }) {
  if (history.length === 0) return null

  return (
    <div className="mt-6">
      <h3 className="text-sm font-medium text-muted-foreground mb-3 flex items-center gap-2">
        <History className="h-4 w-4" /> Status History
      </h3>
      <div className="space-y-0">
        {history.map((entry, index) => (
          <div key={entry.id} className="flex gap-3">
            {/* Timeline line */}
            <div className="flex flex-col items-center">
              <div className={`w-3 h-3 rounded-full border-2 ${index === history.length - 1 ? 'border-primary bg-primary/20' : 'border-muted-foreground/30 bg-background'}`} />
              {index < history.length - 1 && (
                <div className="w-px flex-1 bg-border mt-1" />
              )}
            </div>
            {/* Content */}
            <div className="pb-4">
              <span className={`inline-flex items-center rounded-full px-2 py-0.5 text-xs font-medium ${ORDER_STATUS_COLORS[entry.status as CustomerOrderStatus] || 'bg-gray-100 text-gray-800'}`}>
                {ORDER_STATUS_LABELS[entry.status as CustomerOrderStatus] ?? entry.status}
              </span>
              <div className="text-xs text-muted-foreground mt-1 flex items-center gap-1">
                <Clock className="h-3 w-3" />
                {new Date(entry.transitionedAt).toLocaleString('en-IE', {
                  year: 'numeric',
                  month: 'short',
                  day: '2-digit',
                  hour: '2-digit',
                  minute: '2-digit',
                })}
              </div>
            </div>
          </div>
        ))}
      </div>
    </div>
  )
}

// ---------------------------------------------------------------------------
// Component — Balance Payment Dialog
// ---------------------------------------------------------------------------

interface BalancePaymentDialogProps {
  isOpen: boolean
  onClose: () => void
  balanceDue: number
  onConfirm: (paymentLines: Array<{ method: 'cash' | 'card'; amount: number }>) => void
}

function BalancePaymentDialog({ isOpen, onClose, balanceDue, onConfirm }: BalancePaymentDialogProps) {
  const [method, setMethod] = useState<'cash' | 'card'>('cash')
  const [amount, setAmount] = useState(balanceDue)
  const [processing, setProcessing] = useState(false)

  const handleConfirm = async () => {
    if (amount !== balanceDue) {
      toast.error(`Payment must exactly cover balance due: ${formatCentsToEuro(balanceDue)}`)
      return
    }
    setProcessing(true)
    try {
      onConfirm([{ method, amount }])
    } finally {
      setProcessing(false)
    }
  }

  const handleReset = () => {
    setAmount(balanceDue)
    setMethod('cash')
  }

  return (
    <Dialog open={isOpen} onOpenChange={(open) => { if (!open) onClose(); }}>
      <DialogContent>
        <DialogHeader>
          <DialogTitle className="flex items-center gap-2">
            <CheckCircle2 className="h-5 w-5 text-green-600" />
            Collect Balance Payment
          </DialogTitle>
          <DialogDescription>
            Enter payment details to complete this order.
          </DialogDescription>
        </DialogHeader>

        <div className="space-y-4 py-2">
          {/* Balance Due */}
          <div className="p-3 bg-muted/50 rounded-md text-sm">
            <span className="text-muted-foreground block text-xs mb-1">Balance Due</span>
            <span className="font-mono text-lg font-semibold">{formatCentsToEuro(balanceDue)}</span>
          </div>

          {/* Payment Method */}
          <div>
            <label className="text-sm font-medium mb-2 block">Payment Method</label>
            <div className="flex gap-2">
              <Button
                variant={method === 'cash' ? 'default' : 'outline'}
                size="sm"
                onClick={() => setMethod('cash')}
              >
                Cash
              </Button>
              <Button
                variant={method === 'card' ? 'default' : 'outline'}
                size="sm"
                onClick={() => setMethod('card')}
              >
                Card
              </Button>
            </div>
          </div>

          {/* Amount */}
          <div>
            <label className="text-sm font-medium mb-2 block">Amount (€)</label>
            <input
              type="number"
              step="0.01"
              min="0"
              value={amount / 100 || ''}
              onChange={(e) => setAmount(Math.round(parseFloat(e.target.value || '0') * 100))}
              className="w-full px-3 py-2 border rounded-md text-sm font-mono focus:outline-none focus:ring-2 focus:ring-primary"
            />
          </div>

          {/* Validation */}
          {amount !== balanceDue && (
            <div className="flex items-center gap-2 text-xs text-red-600">
              <AlertTriangle className="h-4 w-4" />
              Amount must exactly match balance due ({formatCentsToEuro(balanceDue)})
            </div>
          )}
        </div>

        <DialogFooter>
          <Button variant="outline" size="sm" onClick={onClose}>
            Cancel
          </Button>
          <Button size="sm" onClick={handleReset} variant="secondary">
            Reset
          </Button>
          <Button
            size="sm"
            onClick={handleConfirm}
            disabled={processing || amount !== balanceDue}
          >
            {processing ? 'Processing…' : 'Collect Payment'}
          </Button>
        </DialogFooter>
      </DialogContent>
    </Dialog>
  )
}

// ---------------------------------------------------------------------------
// Component — Cancel Confirmation Dialog
// ---------------------------------------------------------------------------

interface CancelConfirmDialogProps {
  isOpen: boolean
  onClose: () => void
  currentStatus: CustomerOrderStatus
  depositPaid: number
  onConfirm: () => void
}

function CancelConfirmDialog({ isOpen, onClose, currentStatus, depositPaid, onConfirm }: CancelConfirmDialogProps) {
  const [processing, setProcessing] = useState(false)

  const isRefundable = currentStatus === 'pending' && depositPaid > 0

  const handleConfirm = async () => {
    setProcessing(true)
    try {
      await onConfirm()
    } finally {
      setProcessing(false)
    }
  }

  return (
    <Dialog open={isOpen} onOpenChange={(open) => { if (!open) onClose(); }}>
      <DialogContent>
        <DialogHeader>
          <DialogTitle className="flex items-center gap-2 text-red-600">
            <XCircle className="h-5 w-5" />
            Cancel Order
          </DialogTitle>
          <DialogDescription>
            Are you sure you want to cancel this order? This action cannot be undone.
          </DialogDescription>
        </DialogHeader>

        <div className="space-y-4 py-2">
          {/* Refund Info */}
          {isRefundable ? (
            <div className="p-3 bg-green-50 border border-green-200 rounded-md text-sm dark:bg-green-900/20 dark:border-green-800">
              <div className="flex items-center gap-2 mb-1">
                <CheckCircle2 className="h-4 w-4 text-green-600" />
                <span className="font-medium text-green-700 dark:text-green-400">Deposit Refundable</span>
              </div>
              <p className="text-muted-foreground">
                Since the order is still pending, your deposit of{' '}
                <strong>{formatCentsToEuro(depositPaid)}</strong> will be refunded.
              </p>
            </div>
          ) : (
            <div className="p-3 bg-yellow-50 border border-yellow-200 rounded-md text-sm dark:bg-yellow-900/20 dark:border-yellow-800">
              <div className="flex items-center gap-2 mb-1">
                <AlertTriangle className="h-4 w-4 text-yellow-600" />
                <span className="font-medium text-yellow-700 dark:text-yellow-400">Deposit Non-Refundable</span>
              </div>
              {depositPaid > 0 ? (
                <p className="text-muted-foreground">
                  The deposit of <strong>{formatCentsToEuro(depositPaid)}</strong> is non-refundable at this stage.
                  No automatic financial adjustment will be made — handle externally if needed.
                </p>
              ) : (
                <p className="text-muted-foreground">
                  No deposit was collected for this order.
                </p>
              )}
            </div>
          )}
        </div>

        <DialogFooter>
          <Button variant="outline" size="sm" onClick={onClose}>
            Keep Order
          </Button>
          <Button
            variant="destructive"
            size="sm"
            onClick={handleConfirm}
            disabled={processing}
          >
            {processing ? 'Cancelling…' : 'Cancel Order'}
          </Button>
        </DialogFooter>
      </DialogContent>
    </Dialog>
  )
}

// ---------------------------------------------------------------------------
// Component — Mark Ordered Dialog (with delivery date picker)
// ---------------------------------------------------------------------------

interface MarkOrderedDialogProps {
  isOpen: boolean
  onClose: () => void
  onConfirm: (data: { expectedDeliveryDate?: string | null; internalNotes?: string | null }) => void
}

function MarkOrderedDialog({ isOpen, onClose, onConfirm }: MarkOrderedDialogProps) {
  const [deliveryDate, setDeliveryDate] = useState('')
  const [notes, setNotes] = useState('')
  const [processing, setProcessing] = useState(false)

  const handleConfirm = async () => {
    setProcessing(true)
    try {
      onConfirm({
        expectedDeliveryDate: deliveryDate || null,
        internalNotes: notes || null,
      })
    } finally {
      setProcessing(false)
    }
  }

  return (
    <Dialog open={isOpen} onOpenChange={(open) => { if (!open) onClose(); }}>
      <DialogContent>
        <DialogHeader>
          <DialogTitle className="flex items-center gap-2">
            <CalendarDays className="h-5 w-5 text-blue-600" />
            Mark Order as Ordered
          </DialogTitle>
          <DialogDescription>
            Set the expected delivery date and any internal notes.
          </DialogDescription>
        </DialogHeader>

        <div className="space-y-4 py-2">
          {/* Delivery Date */}
          <div>
            <label className="text-sm font-medium mb-2 block flex items-center gap-1">
              <CalendarDays className="h-4 w-4" /> Expected Delivery Date
            </label>
            <input
              type="date"
              value={deliveryDate}
              onChange={(e) => setDeliveryDate(e.target.value)}
              className="w-full px-3 py-2 border rounded-md text-sm focus:outline-none focus:ring-2 focus:ring-primary"
            />
          </div>

          {/* Internal Notes */}
          <div>
            <label className="text-sm font-medium mb-2 block">Internal Notes</label>
            <textarea
              value={notes}
              onChange={(e) => setNotes(e.target.value)}
              rows={3}
              maxLength={2000}
              placeholder="Optional notes for internal use…"
              className="w-full px-3 py-2 border rounded-md text-sm focus:outline-none focus:ring-2 focus:ring-primary resize-y"
            />
          </div>
        </div>

        <DialogFooter>
          <Button variant="outline" size="sm" onClick={onClose}>
            Cancel
          </Button>
          <Button
            size="sm"
            onClick={handleConfirm}
            disabled={processing}
          >
            {processing ? 'Processing…' : 'Mark Ordered'}
          </Button>
        </DialogFooter>
      </DialogContent>
    </Dialog>
  )
}

