describe('OrderDetailPanel', () => {
  it('renders order number and status badge', async () => {
    const detail = createOrderDetail()
    vi.spyOn(apiModule, 'getOrder').mockResolvedValueOnce(detail)

    renderPanel()

    await waitFor(() => {
      expect(screen.getByText('CO-0001')).toBeInTheDocument()
    })

    expect(screen.getByText('Pending')).toBeInTheDocument()
  })

  it('renders line items table with descriptions and quantities', async () => {
    const detail = createOrderDetail()
    vi.spyOn(apiModule, 'getOrder').mockResolvedValueOnce(detail)

    renderPanel()

    await waitFor(() => {
      expect(screen.getByText('Bearing 6205')).toBeInTheDocument()
      expect(screen.getByText('Installation')).toBeInTheDocument()
    })
  })

  it('displays payment summary when depositPaid > 0', async () => {
    const detail = createOrderDetail({
      depositPaid: 1500,
    })
    vi.spyOn(apiModule, 'getOrder').mockResolvedValueOnce(detail)

    renderPanel()

    await waitFor(() => {
      expect(screen.getByText('Payment Summary')).toBeInTheDocument()
    })
  })

  it('does not display payment summary when depositPaid is 0', async () => {
