    await waitFor(() => {
      expect(screen.queryByText('Payment Summary')).not.toBeInTheDocument()
    })
  })

  it('shows status transition buttons for pending orders', async () => {
    const detail = createOrderDetail({
      order: { ...createOrderDetail().order, status: 'pending' },
    })
    vi.spyOn(apiModule, 'getOrder').mockResolvedValueOnce(detail)

    renderPanel()

    await waitFor(() => {
      expect(screen.getByText('Mark Ordered')).toBeInTheDocument()
      expect(screen.getByText('Cancel Order')).toBeInTheDocument()
    })
  })

  it('shows no transition buttons for fulfilled orders', async () => {
    const detail = createOrderDetail({
      order: { ...createOrderDetail().order, status: 'fulfilled' },
    })
    vi.spyOn(apiModule, 'getOrder').mockResolvedValueOnce(detail)

    renderPanel()

    await waitFor(() => {
      expect(screen.queryByText('Mark Ordered')).not.toBeInTheDocument()
      expect(screen.queryByText('Cancel Order')).not.toBeInTheDocument()
    })
  })

  it('shows no transition buttons for cancelled orders', async () => {
    const detail = createOrderDetail({
      order: { ...createOrderDetail().order, status: 'cancelled' },
    })
    vi.spyOn(apiModule, 'getOrder').mockResolvedValueOnce(detail)

    renderPanel()

    await waitFor(() => {
      expect(screen.queryByText('Mark Ordered')).not.toBeInTheDocument()
      expect(screen.queryByText('Cancel Order')).not.toBeInTheDocument()
    })
  })

  it('displays error when order fetch fails', async () => {
    vi.spyOn(apiModule, 'getOrder').mockRejectedValueOnce(new Error('Failed to load order'))

    renderPanel()

    await waitFor(() => {
      expect(screen.getByText(/Failed to load order/i)).toBeInTheDocument()
    })
  })

  it('displays internal notes when present', async () => {
    const detail = createOrderDetail({
      order: { ...createOrderDetail().order, internalNotes: 'Customer requested express delivery' },
    })
    vi.spyOn(apiModule, 'getOrder').mockResolvedValueOnce(detail)

    renderPanel()

    await waitFor(() => {
      expect(screen.getByText('Internal Notes')).toBeInTheDocument()
      expect(screen.getByText('Customer requested express delivery')).toBeInTheDocument()
    })
  })
})

