  // ---------------------------------------------------------------------------
  // PATCH /api/orders/:id/cancel — Cancel with refund rules
  // ---------------------------------------------------------------------------
  describe('PATCH /api/orders/:id/cancel', () => {
    it('(tracer) should cancel pending order and return refund payment when deposit exists', async () => {
      await db.insert(vatRates).values({ id: 'vat-standard', rate: 2100, description: 'Standard 21%' })

      const body = {
        customerId: 'cust-abc',
        lineItems: [{ lineType: 'part', partId: 'p1', description: 'Part A', quantity: 1, unitPriceNet: 1000, vatRateId: 'vat-standard' }],
        depositAmount: 500,
        paymentMethod: 'cash',
      }

      const createRes = await app.request('/api/orders', { method: 'POST', body: JSON.stringify(body), headers: { 'Content-Type': 'application/json' } })
      const createJson = await createRes.json() as Record<string, unknown>
      const orderId = (createJson.order as Record<string, unknown>).id as string

      const res = await app.request(`/api/orders/${orderId}/cancel`, {
        method: 'PATCH',
        headers: { 'Content-Type': 'application/json' },
      })

      expect(res.status).toBe(200)
      const json = await res.json() as Record<string, unknown>
      expect(json.status).toBe('cancelled')
      // Refund payment created at pending status
      expect(json.refundPayment).toBeDefined()
      expect((json.refundPayment as Record<string, unknown>).amount).toBe(500)
    })

    it('should cancel without refund when no deposit was collected', async () => {
      await db.insert(vatRates).values({ id: 'vat-standard', rate: 2100, description: 'Standard 21%' })

      const body = {
        customerId: 'cust-abc',
        lineItems: [{ lineType: 'part', partId: 'p1', description: 'Part A', quantity: 1, unitPriceNet: 1000, vatRateId: 'vat-standard' }],
      }

      const createRes = await app.request('/api/orders', { method: 'POST', body: JSON.stringify(body), headers: { 'Content-Type': 'application/json' } })
      const createJson = await createRes.json() as Record<string, unknown>
      const orderId = (createJson.order as Record<string, unknown>).id as string

      const res = await app.request(`/api/orders/${orderId}/cancel`, {
        method: 'PATCH',
        headers: { 'Content-Type': 'application/json' },
      })

      expect(res.status).toBe(200)
      const json = await res.json() as Record<string, unknown>
      expect(json.status).toBe('cancelled')
      // No refund when no deposit
      expect(json.refundPayment).toBeUndefined()
    })

    it('should reject cancelling already fulfilled order (409)', async () => {
      await db.insert(vatRates).values({ id: 'vat-standard', rate: 2100, description: 'Standard 21%' })

      const body = {
