  // GET /api/orders/:id/history — Status transition history
  // ---------------------------------------------------------------------------
  describe('GET /api/orders/:id/history', () => {
    it('(tracer) should return empty array for order with no transitions', async () => {
      await db.insert(vatRates).values({ id: 'vat-standard', rate: 2100, description: 'Standard 21%' })

      const body = {
        customerId: 'cust-abc',
        lineItems: [{ lineType: 'part', partId: 'p1', description: 'Part A', quantity: 1, unitPriceNet: 1000, vatRateId: 'vat-standard' }],
      }

      const createRes = await app.request('/api/orders', { method: 'POST', body: JSON.stringify(body), headers: { 'Content-Type': 'application/json' } })
      const createJson = await createRes.json() as Record<string, unknown>
      const orderId = (createJson.order as Record<string, unknown>).id as string

      const res = await app.request(`/api/orders/${orderId}/history`)

      expect(res.status).toBe(200)
      const json = await res.json() as Record<string, unknown>
      expect(json.history).toEqual([])
    })

    it('should return transitions in chronological order (oldest first)', async () => {
      await db.insert(vatRates).values({ id: 'vat-standard', rate: 2100, description: 'Standard 21%' })

      const body = {
        customerId: 'cust-abc',
        lineItems: [{ lineType: 'part', partId: 'p1', description: 'Part A', quantity: 1, unitPriceNet: 1000, vatRateId: 'vat-standard' }],
      }

      const createRes = await app.request('/api/orders', { method: 'POST', body: JSON.stringify(body), headers: { 'Content-Type': 'application/json' } })
      const createJson = await createRes.json() as Record<string, unknown>
      const orderId = (createJson.order as Record<string, unknown>).id as string

      // Transition pending → ordered
      await app.request(`/api/orders/${orderId}/transition`, {
        method: 'PATCH',
        body: JSON.stringify({ status: 'ordered' }),
        headers: { 'Content-Type': 'application/json' },
      })

      // Small delay for timestamp ordering
      await new Promise(r => setTimeout(r, 10))

      // Transition ordered → ready
      await app.request(`/api/orders/${orderId}/transition`, {
        method: 'PATCH',
        body: JSON.stringify({ status: 'ready' }),
        headers: { 'Content-Type': 'application/json' },
      })

      const res = await app.request(`/api/orders/${orderId}/history`)

      expect(res.status).toBe(200)
      const json = await res.json() as Record<string, unknown>
      const history = json.history as Array<Record<string, unknown>>
      expect(history).toHaveLength(2)
      expect(history[0].status).toBe('ordered')
      expect(history[1].status).toBe('ready')
    })

    it('should return 404 for non-existent order', async () => {
      const res = await app.request('/api/orders/nonexistent-id/history')

      expect(res.status).toBe(404)
    })
  })
